pertyNames":{"\$ref":"#/\$defs/VettingRelationship"},"additionalProperties":{"type":"integer","minimum":0},"description":"The most counted statements that may come from vetters declaring each relationship — e.g. `{ \\"family\\": 0 }`."},"requireConsistentIdentityCommitment":{"type":"boolean","description":"When true, every counted statement must carry the same identity commitment — all vetters verified the same claimed identity. Absent: false."}},"description":"Caps on how much evidence may come from people close to the applicant. Absent: no caps."},"invitation":{"type":"string","enum":["required","optional","none"],"description":"Whether an invitation credential must accompany the statements at submission (`required`), may (`optional`), or plays no part (`none`). Absent: the presentation-definition alone governs."},"decisionSla":{"\$ref":"#/\$defs/Duration"},"requirementsGrace":{"\$ref":"#/\$defs/Duration"},"governanceFrameworkUrl":{"type":"string","format":"uri","pattern":"^https://","maxLength":2048,"description":"Where the community\'s vetting governance — including the attestation text vetters sign — is published."}}},"CommunityBranding":{"title":"CommunityBranding","type":"object","additionalProperties":false,"description":"OPTIONAL. How the community asks to be shown to a prospective applicant: a name, an accent colour and a logo. Presentation only, self-asserted and unverified — `communityDid` identifies the community, never `branding`. Not part of any criterion, so not covered by a `requirementsDigest`. Every member is optional.","properties":{"displayName":{"type":"string","minLength":1,"maxLength":128,"description":"The community\'s name as it asks to be shown."},"accentColor":{"type":"string","pattern":"^#[0-9a-fA-F]{6}\$","description":"An sRGB colour as `#rrggbb`, compared case-insensitively. A community SHOULD write it in lower case."},"logoUrl":{"type":"string","format":"uri","pattern":"^https://","maxLength":2048,"description":"An https URL of the community\'s logo. Fetched by the client, so an untrusted image from wherever it points."},"ext":{"\$ref":"#/\$defs/Ext"}}},"Response":{"\$anchor":"response","title":"VTC Join-Requests Manifest — response payload","type":"object","additionalProperties":false,"required":["communityDid","criteria"],"properties":{"communityDid":{"type":"string","pattern":"^did:"},"criteria":{"type":"array","items":{"\$ref":"#/\$defs/Criterion"}},"branding":{"\$ref":"#/\$defs/CommunityBranding"},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"VettingRelationship":{"title":"VettingRelationship","type":"string","enum":["none","communityColleague","sameEmployer","family","otherPersonal"],"description":"The vetter\'s own declaration of how they relate to the applicant. Declared, not verified: it exists so community policy can cap how much evidence comes from people close to the applicant, and a false declaration is the vetter\'s attributable act."},"ClaimType":{"title":"ClaimType","description":"The vocabulary token naming what a value IS — `name.legal`, `phone.mobile`, `address.postal`, `person.birthDate`. Dotted, most-general segment first, so that a consumer with no knowledge of the specific token can still group by its prefix.\\n\\nThe token is the maintainer\'s own; no external vocabulary is primary. External vocabularies (vCard/jCard, OIDC standard claims, schema.org) are mappings applied at PRESENTATION by a renderer, not at rest, so that a query written in any of them can be matched without the store having to live inside any one of them.\\n\\nThe `x:` prefix is an open extension namespace and is not decoration. The closest prior art — Windows CardSpace\'s self-issued card — supported exactly fifteen predefined claim types with no extensibility, and that is the specific way it failed the requirement a holder actually has. An `x:` attribute stores, composes, binds and discloses exactly like a known one; it renders generically and matches only an explicit query.","type":"string","minLength":1,"maxLength":128,"pattern":"^(x:)?[a-z][a-zA-Z0-9]*(\\\\.[a-z][a-zA-Z0-9]*)*\$"},"VettingDocumentation":{"title":"VettingDocumentation","type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z][a-zA-Z0-9]*\$","description":"A class of documentation, named in lowerCamelCase. Open rather than enumerated, because what documentation a vetter accepts is each vetter\'s own choice. Well-known values: `passport`, `nationalId`, `driverLicence`, and `none` — the vetter will attest without a document, which is the `priorAcquaintance` case. Only the class ever travels — never a document number, an image, an issuing authority or an expiry date. `none` states a policy (what a vetter accepts); a record of what was relied on expresses \'no document\' as an empty list instead."},"VettingMethod":{"title":"VettingMethod","type":"string","enum":["inPerson","video","priorAcquaintance"],"description":"How the vetter established that the person they checked is the person controlling the applicant\'s DID. `inPerson` — both people were physically together. `video` — a live, two-way video call. `priorAcquaintance` — the vetter has known or worked with this person over a period, and attests from that knowledge rather than from a document. A method is a description of what happened, not an assurance level: which methods count, and how many of each, is community policy."},"DigestMultibase":{"title":"DigestMultibase","description":"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\"interoperability is not guaranteed between implementations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]}}}';

